# -*- coding: utf-8 -*-
"""12. kor (1.2.1): 50 uj tura a ritka/ures teruletekre. Sorrend: add_r12 -> tours_order <r12_ids> -> dup_check -> poi_registry -> tours_kw -> tours_img -> tours_check"""
from tourlib import *
import json, os
C = lambda e, h: (e, h)
CONT = {}
POI = {}


def add(cont, *a):
    a = list(a)
    a.insert(6, [])
    tour(*a); CONT[a[0]] = cont


def Pt(n, hu, kw, la, lo):
    POI[n] = (hu, kw)
    return [n, la, lo]


def L(ic, pts, name, desc, kind="loop", kt=100, alt=3000, vid="loop"):
    """Egy korut: ic = indulo es erkezo repter."""
    return [(vid, kind, kt, alt, name, desc, [ic] + pts + [ic])]


